import com.nylas.NylasClient;
import com.nylas.models.Configuration;
import com.nylas.models.ConfigurationAvailability;
import com.nylas.models.ConfigurationAvailabilityParticipant;
import com.nylas.models.ConfigurationBookingParticipant;
import com.nylas.models.ConfigurationEventBooking;
import com.nylas.models.ConfigurationParticipant;
import com.nylas.models.CreateConfigurationRequest;
import com.nylas.models.NylasApiError;
import com.nylas.models.NylasSdkTimeoutError;
import com.nylas.models.Response;
import java.util.Collections;
import java.util.List;

public class CreateConfiguration {
  public static void main(String[] args) throws NylasSdkTimeoutError, NylasApiError {
    NylasClient nylas = new NylasClient.Builder("<NYLAS_API_KEY>").build();

    ConfigurationParticipant participant = new ConfigurationParticipant.Builder("host@example.com")
        .isOrganizer(true)
        .availability(new ConfigurationAvailabilityParticipant.Builder()
            .calendarIds(Collections.singletonList("primary"))
            .build())
        .booking(new ConfigurationBookingParticipant.Builder()
            .calendarId("primary")
            .build())
        .build();

    ConfigurationAvailability availability = new ConfigurationAvailability.Builder()
        .durationMinutes(30)
        .build();

    ConfigurationEventBooking eventBooking = new ConfigurationEventBooking.Builder()
        .title("30-minute meeting")
        .build();

    CreateConfigurationRequest requestBody = new CreateConfigurationRequest.Builder(
        Collections.singletonList(participant), availability, eventBooking)
        .build();

    Response<Configuration> configuration = nylas.scheduler().configurations()
        .create("<NYLAS_GRANT_ID>", requestBody);

    System.out.println("Configuration: " + configuration.getData());
  }
}

